style.css:
@-moz-document domain("youtube.com") {
/* Fondo del buscador */
  #search-form, #search-container {
    background-color: #ffd6ec !important; /* rosita claro */
    border-radius: 10px !important;
  }

  /* Campo de entrada del buscador */
  #search-input, input#search {
    background-color: #ffeaf4 !important; /* aún más claro */
    color: #d4006f !important; /* rosa más fuerte */
    border: none !important;
  }

  /* Botón de búsqueda (icono lupa) */
  button#search-icon-legacy {
    background-color: #ffb6d9 !important; /* fondo del botón */
    color: #d4006f !important; /* color del icono */
    border-radius: 6px !important;
  }

  /* Efecto al pasar el ratón */
  #search-form:hover, #search-input:hover {
    background-color: #ffe0f0 !important;
  }
}
